window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e9271f9822b290cb"]={"versions": [{"id": "FIG-e9271f9822b290cb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens beim PDU-Empfang (PDU reception) im AUTOSAR Classic Platform Basissoftware-Modul <code>UdpNm</code> (UDP Network Management). Das Diagramm stellt das Zusammenspiel zwischen dem Kommunikationsmodul <code>SoAd</code> (Socket Adaptor), der State Machine bzw. Logik des Moduls <code>:UdpNm</code> sowie den beiden logischen Timern <code>Message Cycle Timer</code> und <code>Message Timeout Timer</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen / Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>«Module» :UdpNm</code>: Das UDP-Netzwerkmanagement-Modul als Empfänger der Netzwerk-PDU und Steuerinstanz des Überwachungstimers.\n</li><li><code>Message Cycle Timer</code>: Logischer Timer zur zyklischen Sendeüberwachung bzw. Sendeauslösung (im Empfangsszenario passiv dargestellt).\n</li><li><code>Message Timeout Timer</code>: Überwachungstimer (<code>UdpNmTimeoutTime</code>) zur Erkennung des Ausbleibens von NM-Botschaften auf dem Netzwerk.\n</li><li><code>«Module» :SoAd</code>: Socket-Adaptor-Modul der Kommunikationsschicht als Aufrufer der Empfangsindikation.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>UdpNm_SoAdIfRxIndication(PduIdType, PduInfoType*)</code>: Synchrone Aufrufschnittstelle (Callback) von <code>SoAd</code> an <code>UdpNm</code> zur Übergabe einer empfangenen NM-PDU mit Parametern für PDU-Identifier (<code>PduIdType</code>) und Zeiger auf PDU-Metadaten/Nutzdaten (<code>PduInfoType*</code>).\n</li><li><code>UdpNm_SoAdIfRxIndication()</code>: Rückkehr (Return-Pfeil, gestrichelt) an das aufrufende <code>SoAd</code>-Modul nach Abschluss der synchronen Empfangsverarbeitung.\n</li><li><code>StartTimer(UdpNmTimeoutTime)</code>: Interner Steuerungsaufruf zum Starten bzw. Neustarten des <code>Message Timeout Timer</code> mit dem konfigurierten Timeout-Wert <code>UdpNmTimeoutTime</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Einbettung in ein Interaktionsfragment <code>loop</code> mit dem Prädikat bzw. der Bedingung <code>repeated for every transmission</code> (greift bei jedem Botschaftsempfang).\n</li><li><code>SoAd</code> empfängt ein UDP-Paket und signalisiert dieses synchron an <code>UdpNm</code> über den Aufruf <code>UdpNm_SoAdIfRxIndication(PduIdType, PduInfoType*)</code>.\n</li><li>Während des resultierenden Ausführungsfokus (Execution Specification) auf der Lebenslinie von <code>:UdpNm</code> wird der Aufruf beendet und die synchrone Antwort (<code>UdpNm_SoAdIfRxIndication()</code>) kehrt zu <code>SoAd</code> zurück.\n</li><li>Unmittelbar im Anschluss initiiert <code>:UdpNm</code> mit <code>StartTimer(UdpNmTimeoutTime)</code> den Neustart des <code>Message Timeout Timer</code>, um den Timeout-Überwachungszeitraum für nachfolgende Botschaften zurückzusetzen.\n</li><li>Die Lebenslinie des <code>Message Cycle Timer</code> bleibt während dieser Interaktion inaktiv.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Empfangspfad-Verarbeitung:</strong> Die Funktion <code>UdpNm_SoAdIfRxIndication</code> bildet den standardisierten Einsprungpunkt des Socket Adaptors in das UDP Network Management gemäß AUTOSAR-SWS-Spezifikation.\n</li><li><strong>Timer-Reset:</strong> Bei jedem gültigen Botschaftsempfang muss der <code>Message Timeout Timer</code> zurückgesetzt und neu gestartet werden, um den Übergang in einen NM-Timeout-Zustand (z. B. Vorbereitung zum Bus-Schlaf) zu verhindern.\n</li><li><strong>Rückgabe &amp; Entkopplung:</strong> Die synchrone Ausführung des Indikations-Callbacks muss deterministisch und zeitnah zurückkehren; weiterführende Aktionen (wie das Neuaufsetzen des Timeout-Timers) erfolgen im Kontext des NM-Moduls.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0660237413a9bda4", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens beim PDU-Empfang (PDU reception) im AUTOSAR Classic Platform Basissoftware-Modul <code>UdpNm</code> (UDP Network Management). Das Diagramm stellt das Zusammenspiel zwischen dem Kommunikationsmodul <code>SoAd</code> (Socket Adaptor), der State Machine bzw. Logik des Moduls <code>:UdpNm</code> sowie den beiden logischen Timern <code>Message Cycle Timer</code> und <code>Message Timeout Timer</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen / Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>«Module» :UdpNm</code>: Das UDP-Netzwerkmanagement-Modul als Empfänger der Netzwerk-PDU und Steuerinstanz des Überwachungstimers.\n</li><li><code>Message Cycle Timer</code>: Logischer Timer zur zyklischen Sendeüberwachung bzw. Sendeauslösung (im Empfangsszenario passiv dargestellt).\n</li><li><code>Message Timeout Timer</code>: Überwachungstimer (<code>UdpNmTimeoutTime</code>) zur Erkennung des Ausbleibens von NM-Botschaften auf dem Netzwerk.\n</li><li><code>«Module» :SoAd</code>: Socket-Adaptor-Modul der Kommunikationsschicht als Aufrufer der Empfangsindikation.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>UdpNm_SoAdIfRxIndication(PduIdType, PduInfoType*)</code>: Synchrone Aufrufschnittstelle (Callback) von <code>SoAd</code> an <code>UdpNm</code> zur Übergabe einer empfangenen NM-PDU mit Parametern für PDU-Identifier (<code>PduIdType</code>) und Zeiger auf PDU-Metadaten/Nutzdaten (<code>PduInfoType*</code>).\n</li><li><code>UdpNm_SoAdIfRxIndication()</code>: Rückkehr (Return-Pfeil, gestrichelt) an das aufrufende <code>SoAd</code>-Modul nach Abschluss der synchronen Empfangsverarbeitung.\n</li><li><code>StartTimer(UdpNmTimeoutTime)</code>: Interner Steuerungsaufruf zum Starten bzw. Neustarten des <code>Message Timeout Timer</code> mit dem konfigurierten Timeout-Wert <code>UdpNmTimeoutTime</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Einbettung in ein Interaktionsfragment <code>loop</code> mit dem Prädikat bzw. der Bedingung <code>repeated for every transmission</code> (greift bei jedem Botschaftsempfang).\n</li><li><code>SoAd</code> empfängt ein UDP-Paket und signalisiert dieses synchron an <code>UdpNm</code> über den Aufruf <code>UdpNm_SoAdIfRxIndication(PduIdType, PduInfoType*)</code>.\n</li><li>Während des resultierenden Ausführungsfokus (Execution Specification) auf der Lebenslinie von <code>:UdpNm</code> wird der Aufruf beendet und die synchrone Antwort (<code>UdpNm_SoAdIfRxIndication()</code>) kehrt zu <code>SoAd</code> zurück.\n</li><li>Unmittelbar im Anschluss initiiert <code>:UdpNm</code> mit <code>StartTimer(UdpNmTimeoutTime)</code> den Neustart des <code>Message Timeout Timer</code>, um den Timeout-Überwachungszeitraum für nachfolgende Botschaften zurückzusetzen.\n</li><li>Die Lebenslinie des <code>Message Cycle Timer</code> bleibt während dieser Interaktion inaktiv.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Empfangspfad-Verarbeitung:</strong> Die Funktion <code>UdpNm_SoAdIfRxIndication</code> bildet den standardisierten Einsprungpunkt des Socket Adaptors in das UDP Network Management gemäß AUTOSAR-SWS-Spezifikation.\n</li><li><strong>Timer-Reset:</strong> Bei jedem gültigen Botschaftsempfang muss der <code>Message Timeout Timer</code> zurückgesetzt und neu gestartet werden, um den Übergang in einen NM-Timeout-Zustand (z. B. Vorbereitung zum Bus-Schlaf) zu verhindern.\n</li><li><strong>Rückgabe &amp; Entkopplung:</strong> Die synchrone Ausführung des Indikations-Callbacks muss deterministisch und zeitnah zurückkehren; weiterführende Aktionen (wie das Neuaufsetzen des Timeout-Timers) erfolgen im Kontext des NM-Moduls.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-16693105407c8c2f", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens beim PDU-Empfang (PDU reception) im AUTOSAR Classic Platform Basissoftware-Modul <code>UdpNm</code> (UDP Network Management). Das Diagramm stellt das Zusammenspiel zwischen dem Kommunikationsmodul <code>SoAd</code> (Socket Adaptor), der State Machine bzw. Logik des Moduls <code>:UdpNm</code> sowie den beiden logischen Timern <code>Message Cycle Timer</code> und <code>Message Timeout Timer</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen / Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>«Module» :UdpNm</code>: Das UDP-Netzwerkmanagement-Modul als Empfänger der Netzwerk-PDU und Steuerinstanz des Überwachungstimers.\n</li><li><code>Message Cycle Timer</code>: Logischer Timer zur zyklischen Sendeüberwachung bzw. Sendeauslösung (im Empfangsszenario passiv dargestellt).\n</li><li><code>Message Timeout Timer</code>: Überwachungstimer (<code>UdpNmTimeoutTime</code>) zur Erkennung des Ausbleibens von NM-Botschaften auf dem Netzwerk.\n</li><li><code>«Module» :SoAd</code>: Socket-Adaptor-Modul der Kommunikationsschicht als Aufrufer der Empfangsindikation.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>UdpNm_SoAdIfRxIndication(PduIdType, PduInfoType*)</code>: Synchrone Aufrufschnittstelle (Callback) von <code>SoAd</code> an <code>UdpNm</code> zur Übergabe einer empfangenen NM-PDU mit Parametern für PDU-Identifier (<code>PduIdType</code>) und Zeiger auf PDU-Metadaten/Nutzdaten (<code>PduInfoType*</code>).\n</li><li><code>UdpNm_SoAdIfRxIndication()</code>: Rückkehr (Return-Pfeil, gestrichelt) an das aufrufende <code>SoAd</code>-Modul nach Abschluss der synchronen Empfangsverarbeitung.\n</li><li><code>StartTimer(UdpNmTimeoutTime)</code>: Interner Steuerungsaufruf zum Starten bzw. Neustarten des <code>Message Timeout Timer</code> mit dem konfigurierten Timeout-Wert <code>UdpNmTimeoutTime</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Einbettung in ein Interaktionsfragment <code>loop</code> mit dem Prädikat bzw. der Bedingung <code>repeated for every transmission</code> (greift bei jedem Botschaftsempfang).\n</li><li><code>SoAd</code> empfängt ein UDP-Paket und signalisiert dieses synchron an <code>UdpNm</code> über den Aufruf <code>UdpNm_SoAdIfRxIndication(PduIdType, PduInfoType*)</code>.\n</li><li>Während des resultierenden Ausführungsfokus (Execution Specification) auf der Lebenslinie von <code>:UdpNm</code> wird der Aufruf beendet und die synchrone Antwort (<code>UdpNm_SoAdIfRxIndication()</code>) kehrt zu <code>SoAd</code> zurück.\n</li><li>Unmittelbar im Anschluss initiiert <code>:UdpNm</code> mit <code>StartTimer(UdpNmTimeoutTime)</code> den Neustart des <code>Message Timeout Timer</code>, um den Timeout-Überwachungszeitraum für nachfolgende Botschaften zurückzusetzen.\n</li><li>Die Lebenslinie des <code>Message Cycle Timer</code> bleibt während dieser Interaktion inaktiv.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Empfangspfad-Verarbeitung:</strong> Die Funktion <code>UdpNm_SoAdIfRxIndication</code> bildet den standardisierten Einsprungpunkt des Socket Adaptors in das UDP Network Management gemäß AUTOSAR-SWS-Spezifikation.\n</li><li><strong>Timer-Reset:</strong> Bei jedem gültigen Botschaftsempfang muss der <code>Message Timeout Timer</code> zurückgesetzt und neu gestartet werden, um den Übergang in einen NM-Timeout-Zustand (z. B. Vorbereitung zum Bus-Schlaf) zu verhindern.\n</li><li><strong>Rückgabe &amp; Entkopplung:</strong> Die synchrone Ausführung des Indikations-Callbacks muss deterministisch und zeitnah zurückkehren; weiterführende Aktionen (wie das Neuaufsetzen des Timeout-Timers) erfolgen im Kontext des NM-Moduls.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e9271f9822b290cb", "to": "FIG-0660237413a9bda4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0660237413a9bda4", "to": "FIG-16693105407c8c2f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
